<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class ScholarshipController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('social_teacher'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$commissions=DB::table('scholarship_commissions')->where('academic_period_id',$p->id)->orderByDesc('meeting_on')->get();$decisions=DB::table('scholarship_decisions as d')->join('scholarship_commissions as c','c.id','=','d.scholarship_commission_id')->join('students as s','s.id','=','d.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('c.academic_period_id',$p->id)->select('d.*','c.protocol_number','c.meeting_on','s.last_name','s.first_name','s.middle_name','g.name as group_name')->orderByDesc('c.meeting_on')->orderBy('s.last_name')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$social=DB::table('student_social_statuses as ss')->join('student_social_categories as sc','sc.id','=','ss.category_id')->where('ss.status','active')->where(fn($q)=>$q->whereNull('ss.valid_until')->orWhere('ss.valid_until','>=',today()))->select('ss.id','ss.student_id','sc.name')->get()->groupBy('student_id');return view('upbringing.scholarships',compact('p','commissions','decisions','students','social'));}
 public function commission(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['protocol_number'=>'required|string|max:100','meeting_on'=>'required|date','note'=>'nullable|string|max:5000']);DB::table('scholarship_commissions')->insert($d+['academic_period_id'=>$p->id,'status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Заседание комиссии создано');}
 public function decision(Request $r,$commission){$this->ok($r);$c=DB::table('scholarship_commissions')->find($commission);abort_if(!$c,404);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['student_id'=>'required|exists:students,id','type'=>'required|in:academic,social,named,material_aid','amount'=>'nullable|numeric|min:0','starts_on'=>'nullable|date','ends_on'=>'nullable|date|after_or_equal:starts_on','decision'=>'required|in:assigned,denied,stopped','basis'=>'nullable|string|max:5000','social_status_id'=>'nullable|exists:student_social_statuses,id']);if(($d['type']==='social'||$d['type']==='material_aid')&&!empty($d['social_status_id']))abort_unless(DB::table('student_social_statuses')->where(['id'=>$d['social_status_id'],'student_id'=>$d['student_id'],'status'=>'active'])->exists(),422,'Социальный статус не принадлежит выбранному студенту или закрыт.');DB::table('scholarship_decisions')->insert($d+['scholarship_commission_id'=>$commission,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Решение комиссии добавлено');}
}